([k,a,t])=>{const s=JSON.parse(localStorage.getItem(k));GSDemoClinicAssociations.repair(s);for(const u of [...s.users,...Object.values(s.employees||{})]){u.name='SYN '+u.id;u.email=u.id+'@example.invalid'}for(const c of s.clinics){c.name='SYN Clínica '+c.id;c.address='Rua Sintética'}s.currentUser=a;s.ceoViewingAs=a==='u1'?null:a;const u=s.employees[a]||s.users.find(x=>x.id===a),allowed=AccessScopeV4.activeClinics(s).filter(c=>a==='u1'||AccessScopeV4.assigned(u).includes(String(c.id))),cid=String(allowed[0].id);s.days={};s.requests=[];for(let i=0;i<7;i++){const date='2026-10-'+String(19+i),d=date+'_'+cid;s.days[d]={clinic:cid,date,revision:1,openedAt:date+'T08:00:00Z',closed:true,open:{saved:true,professionals:[{employeeId:'test_med',kind:'doctor',category:'consultations',selected:true,consults:20+i,booked:20+i,currentBooked:20+i},{employeeId:'test_tec',kind:'therapist',category:'treatments',selected:true,consults:30,capacity:32,currentBooked:30}]},close:{saved:true,professionals:[{employeeId:'test_med',kind:'doctor',category:'consultations',done:17+i},{employeeId:'test_tec',kind:'therapist',done:25+i%3}]},indicators:{},taskStatus:{synthetic:{status:i<3?'done':'todo'}},taskCatalog:[{id:'synthetic',name:'SYN Conferência',active:true,clinics:[cid]}]};s.requests.push({id:'SYN-wait-'+i,clinic:cid,name:'SYN contacto '+i,patientRef:'SYN-'+i,specialty:'SYN Especialidade',stage:i<5?'Novo pedido':'Marcado',created:date+'T12:00:00Z',completed:i>=5?date+'T15:00:00Z':null,history:[]})}s.alerts=[{id:'SYN-alert',clinic:cid,title:'SYN Conferir documento operacional',status:'Pendente',to:a}];localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('gs-v4-theme:'+a,t);return JSON.stringify(s)}
